const first = $input.first().json || {};
if (!Array.isArray(first.data) || !first.meta) throw new Error('Invalid customer cohort response');
const totalPages = Number(first.meta.totalPages);
const expectedTotal = Number(first.meta.total);
const limit = Number(first.meta.limit);
if (!Number.isInteger(totalPages) || totalPages < 0 || totalPages > 1000 || !Number.isInteger(expectedTotal) || expectedTotal < 0 || !Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('Invalid cohort pagination metadata');
if (expectedTotal === 0) { if (totalPages !== 0 || first.data.length !== 0) throw new Error('Inconsistent empty customer cohort response'); return []; }
if (totalPages < 1) throw new Error('Non-empty cohort has no pages');
const customers = [...first.data];
const baseUrl = $env.CRM_API_BASE_URL;
const apiKey = $env.N8N_API_KEY;
if (!baseUrl || !apiKey) throw new Error('CRM_API_BASE_URL and N8N_API_KEY are required');
for (let page = 2; page <= totalPages; page++) {
  const response = await this.helpers.httpRequest({ method: 'GET', url: baseUrl.replace(/\/$/, '') + '/internal/n8n/customers?page=' + page + '&limit=' + limit, headers: { 'x-n8n-api-key': apiKey }, json: true, timeout: 30000 });
  if (!response || !Array.isArray(response.data)) throw new Error('Invalid customer cohort page ' + page);
  customers.push(...response.data);
}
if (customers.length !== expectedTotal) throw new Error('Customer cohort pagination incomplete');
return customers.map(customer => ({ json: customer }));

const customer = $input.first().json || {};
const customerId = customer.id;
const executionId = String($execution.id || '');
if (!customerId || !executionId) throw new Error('Missing customerId or n8n execution ID');
return [{ json: { customerId, customerName: customer.name || null, correlationId: 'wf06:' + executionId + ':' + customerId } }];

const context = $input.first().json || {};
const prepared = $('4. Prepare Customer Context').first().json;
if (!context.customer || context.customer.id !== prepared.customerId) throw new Error('Customer context mismatch');
const evidence = Array.isArray(context.evidence) ? context.evidence : [];
return [{ json: { customerId: context.customer.id, asOfDate: new Date().toISOString().slice(0, 10), evidence, coverage: context.coverage || {}, signals: context.signals || {}, correlationId: prepared.correlationId } }];

const response = $input.first().json || {};
const riskLevels = ['LOW', 'MEDIUM', 'HIGH', 'INSUFFICIENT_DATA'];
if (!response.id || !riskLevels.includes(response.riskLevel)) throw new Error('Backend assessment response is invalid');
if (response.score !== null && (typeof response.score !== 'number' || response.score < 0 || response.score > 100)) throw new Error('Backend assessment score is invalid');
return [{ json: { customerId: $('6. Normalize Feature Snapshot').first().json.customerId, assessmentId: response.id, score: response.score ?? null, riskLevel: response.riskLevel, evidence: Array.isArray(response.evidence) ? response.evidence : [], coverage: response.coverage || {}, correlationId: $('6. Normalize Feature Snapshot').first().json.correlationId } }];

const official = $('8. Validate Assessment Result').first().json;
const response = $input.first().json || {};
let parsed = response;
try { if (typeof response === 'string') parsed = JSON.parse(response); else if (typeof response.text === 'string') parsed = JSON.parse(response.text); } catch { parsed = {}; }
const summary = typeof parsed.summary === 'string' ? parsed.summary : '';
const claims = Array.isArray(parsed.evidence) ? parsed.evidence : [];
const allowedEvidence = new Set(official.evidence.map(item => JSON.stringify(item)));
const evidence = claims.filter(item => typeof item === 'string' && allowedEvidence.has(item));
const confidence = typeof parsed.confidence === 'number' && parsed.confidence >= 0 && parsed.confidence <= 1 ? parsed.confidence : 0;
return [{ json: { ...official, explanation: summary, explanationEvidence: evidence, explanationConfidence: confidence } }];
